examples.safe:
function loadSettings() {
  const incoming = JSON.parse(localStorage.getItem('settings') ?? '{}');
  // Create a prototype-less target to nullify __proto__ writes
  const target = Object.create(null);
  target.theme = 'light';
  for (const k of ['theme','fontSize','locale']) if (k in incoming) target[k] = incoming[k];
  return target;
}
